MATCH (:PlantItem {tag: 'TK-102'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'P-601A'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (p:PlantItem {tag: 'P-302B'}), (v:PlantItem:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:PlantItem:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (target:PlantItem {tag: 'V-201'}), (valve:Valve)-[:line_to]-(target), (loop:ProcessControlFunction)-[:send_signal_to*1..]->(actuator:PlantItem)-[:control]->(valve)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:line_to*1..]->(v:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-601B'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-501'})-[:line_to*1..]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment)-[:measured_by]->(instrument:ProcessInstrumentationFunction {loop_tag: 'TI-5024'})
RETURN equipment.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'V-201'}), (b:PlantItem {tag: 'P-201A'}), (v:Valve)
WHERE v <> a
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:PlantItem:BallValve {unit_id: '4'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-101A'}), (b:PlantItem {tag: 'T-301'})
RETURN EXISTS {
  MATCH p = shortestPath((a)-[:line_to*]->(b))
  WHERE none(n IN nodes(p) WHERE n.tag = 'BFV-1002')
} AS can_flow_without_BFV_1002

MATCH (item:PlantItem {tag: 'P-301B'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-601B'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)
WHERE EXISTS {
  (s)-[:send_signal_to*0..]->(:ProcessInstrumentationFunction {loop_tag: 'TIAH-3037'})
}
RETURN DISTINCT e.tag AS tag
ORDER BY tag

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'LSHH-6004'})-[:send_signal_to*1..]->(a:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-302B'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet
ORDER BY sheet;

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'P-301B'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:BallValve:PlantItem {unit_id: '3'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-103'}), (b:PlantItem {tag: 'T-301'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*1..]->(b))
         WHERE ALL(n IN nodes(p) WHERE n.tag <> 'GTV-2001')
       } AS can_flow_without_GTV-2001

MATCH (a:PlantItem {tag: 'TK-103'}), (b:PlantItem {tag: 'T-301'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*1..]->(b))
         WHERE ALL(n IN nodes(p) WHERE n.tag <> 'GTV-2001')
       } AS can_flow_without_GTV_2001

MATCH (a:PlantItem {tag: 'TK-104'}), (b:PlantItem {tag: 'T-301'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem WHERE x.tag <> 'GV-1001')-[:line_to]->()){1,} (b)
       } AS can_flow_without_valve

MATCH (a:PlantItem {tag: 'P-301A'}), (b:PlantItem {tag: 'P-302B'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'TK-102'}), (b:PlantItem {tag: 'P-302A'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EA-301'}), (b:PlantItem {tag: 'P-401A'})
RETURN a.tag AS source_tag, b.tag AS target_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x.tag <> 'BFV-3006' AND y.tag <> 'BFV-3006')+ (b)
       } AS reachable_without_BFV_3006
